"    // Simulate race condition:
    // When Send #1 is in progress (e.g. right as invoice is locked/processed),
    // Send #2 executes or another concurrent worker inserts the counter row.
    // In unpatched code with firstOrCreate, concurrent attempts crash with duplicate key exception.
    $firstSendHooked = false;
    Invoice::updating(function ($invoice) use (&$firstSendHooked, $draft2, $futureDate) {
        if (! $firstSendHooked && $invoice->status === InvoiceStatus::SENT) {
            $firstSendHooked = true;
            // Interleaved second send
            $this->sendService->send($draft2, $futureDate);
        }
    });

    $sent1 = $this->sendService->send($draft1, $futureDate);
    $sent2 = $draft2->fresh();

    expect($sent1->status)->toBe(InvoiceStatus::SENT);
    expect($sent2->status)->toBe(InvoiceStatus::SENT);

    $allocatedNumbers = collect([$sent1->invoice_number, $sent2->invoice_number])->sort()->values()->all();
    expect($allocatedNumbers)->toBe([
        "VI/{$fy}/0001",
        "VI/{$fy}/0002",
    ]);

    expect(FinancialYearCounter::where('financial_year', $fy)->first()->last_sequence)->toBe(2);
});"

